import{_ as a,C as i,o as u,c as m,a3 as e,E as l,w as p,a as n,j as t}from"./chunks/framework.D3kUw6rp.js";const d="/assets/2.BbEJ5uRL.jpeg",g="/assets/1.B5dWiVTu.jpeg",_="/assets/3.BGGc8qpm.jpeg",f="/assets/4.kVGH108F.jpeg",j="/assets/1.BjvJsDCA.jpeg",T="/assets/2.BYwCM-zN.jpeg",B="/assets/4.Da4ctfXd.jpeg",b="/assets/3.BcoDM2_4.jpeg",x="/assets/5.BCsM9qv1.jpeg",P="/assets/1.Db1394HI.jpeg",q="/assets/2.CNryrhhq.jpeg",C="/assets/3.BmdPeLc0.jpeg",k="/assets/4.DfzNEYH_.jpeg",A="/assets/5.D0Ibo4QM.jpeg",E="/assets/6.C4-glrrB.jpeg",S="/assets/7.C5ffLMWQ.jpeg",V="/assets/8.BkRMZ291.jpeg",N="/assets/9.CCbuHyz6.jpeg",D="/assets/%E6%B5%B7%E6%B2%A7%E7%9F%B3%E5%A1%98%E5%87%BA%E7%A7%9F%E5%B1%8B.BrSLgeFm.mp4",I="/assets/1.CqTATsZW.jpeg",v="/assets/2.BbuOPvhw.jpeg",w="/assets/3.G9k3JQLk.png",G="/assets/4.Ekj3WY_s.png",M="/assets/5.B633s9GG.jpeg",Q=JSON.parse('{"title":"我的租房经历","description":"","frontmatter":{},"headers":[],"relativePath":"article/2024/rental-houses/index.md","filePath":"article/2024/rental-houses/index.md"}'),L={name:"article/2024/rental-houses/index.md"};function R(W,s,F,H,J,$){const r=i("Tip"),o=i("Pictures");return u(),m("div",null,[s[13]||(s[13]=e('<h1 id="我的租房经历" tabindex="-1">我的租房经历 <a class="header-anchor" href="#我的租房经历" aria-label="Permalink to &quot;我的租房经历&quot;">​</a></h1><p>在过去的 10 年中，我有五六次租房的经历。有体验特别好的，也经历过非常糟糕的。</p><p>体验舒适的，会让你想买房，觉得体验肯定会更上一层楼。</p><p>体验糟糕的，会让你迫切想买房，早点摆脱当下的困境。</p><p>所以我们似乎无法跳出房地产的坑，你必须往里跳。</p><p>其实房地产坑不坑，在于你是否从中获得红利。得到了就沾沾自喜，吃亏了就说它是坑，普通人最重要的还是摆正自己的心态。</p><p>当然，中国的房地产是魔幻的，金融属性大于居住属性，你会因为它身价翻倍，也可以因为它掏空所有。最可笑的是，有的人掏空所有之后，什么都得不到。普通人在这样魔幻的时代下，拒绝往里跳才是最明智的。当家的不会给你兜底，你只能自己保持清醒。提升自己的宏观认知，真的可以少踩一些坑。好像扯远了，回到租房经历吧。</p><h2 id="学校附近的民房-😄" tabindex="-1">学校附近的民房 😄 <a class="header-anchor" href="#学校附近的民房-😄" aria-label="Permalink to &quot;学校附近的民房 😄&quot;">​</a></h2><p>第一个出租屋是之前大学附近的民房，可以说是体验最好的一段经历了，房租才 150 块，不可思议！加上网费 30 块，每个月就 200 多的房租开销。对刚参加的我来说太友好了。缺点就是在岛外，每天要坐公交车来软件园二期上班，通勤时间比较多。</p><p>那个房间很小，但是对我够用，我喜欢东西少的状态。采光好，通风好，夜里也很安静。</p><p>后面是由于实在受不了每天挤公交，长时间的通勤，换到岛内的下边社。</p><h2 id="湖里下边社-😄" tabindex="-1">湖里下边社 😄 <a class="header-anchor" href="#湖里下边社-😄" aria-label="Permalink to &quot;湖里下边社 😄&quot;">​</a></h2><p>是和堂姐袁思彤一起租，后面阿坤，阿森都有在这边住过。这个房东也是很好的一个人，房租低，才收 250 块，水费免费。</p><p>当时袁思彤，阿坤，我，还有袁思彤的同学，学妹都住这边，可以说入住群体的素质水平是非常高的。所以体验很棒，基本没有受到过什么噪音烦恼。</p><p>这边去湿地公园还特别近，偶尔下班会过去散步。</p><p>唯一的缺点就是由于采光不好，有点潮。当时恩灵住隔壁栋，加上阿坤，我们三经常下班了混一起玩。</p><p><img src="'+d+'" alt=""></p>',17)),l(r,null,{default:p(()=>[...s[0]||(s[0]=[n("当时的装逼摆拍",-1)])]),_:1}),s[14]||(s[14]=t("p",null,[t("img",{src:g,alt:""})],-1)),l(r,null,{default:p(()=>[...s[1]||(s[1]=[n("在袁思彤的厨房做饭吃",-1)])]),_:1}),l(o,null,{default:p(()=>[...s[2]||(s[2]=[t("img",{src:_},null,-1),t("img",{src:f},null,-1)])]),_:1}),s[15]||(s[15]=t("p",null,"和大家租同一栋楼，下班可以一起玩的感觉很好。后面恩灵和阿坤都相继去了深圳，我也由于工作换到了海沧，搬到海沧的石塘村了。",-1)),s[16]||(s[16]=t("h2",{id:"海沧石塘村-😄",tabindex:"-1"},[n("海沧石塘村 😄 "),t("a",{class:"header-anchor",href:"#海沧石塘村-😄","aria-label":'Permalink to "海沧石塘村 😄"'},"​")],-1)),s[17]||(s[17]=t("p",null,"在海沧石塘村住的房间是在走廊尽头，所以有两面采光，环境很安静。非常标准的单间，一个人住非常合适。房租只要 550 每月。",-1)),s[18]||(s[18]=t("p",null,"这边的居住体验还是挺好的，有种孤独又惬意的感觉。因为这边只有自己一个人，回到宿舍也没人说话，就可以自在的玩电脑，写代码。",-1)),s[19]||(s[19]=t("p",null,[t("img",{src:j,alt:""})],-1)),l(r,null,{default:p(()=>[...s[3]||(s[3]=[n("算是最有学习状态的一段时间",-1)])]),_:1}),s[20]||(s[20]=t("p",null,"石塘村非常很热闹，烟火气旺盛，哪怕是晚上 11 点走在那条路上，都很多人。吃得很多，我最喜欢吃一家铁板豆腐和肥肠面。",-1)),s[21]||(s[21]=t("p",null,"2017 年苏小姐从福州搬来厦门，我们正式在这个出租房同居了。她的东西超级多，瞬间塞满了小小的房间。",-1)),s[22]||(s[22]=t("img",{class:"max-w-500 center",src:T},null,-1)),l(r,null,{default:p(()=>[...s[4]||(s[4]=[n("刚来第一天",-1)])]),_:1}),s[23]||(s[23]=t("p",null,"为了迎接她的到来我提前买了几个箱子和衣架用来装衣服。",-1)),l(o,null,{default:p(()=>[...s[5]||(s[5]=[t("img",{src:B},null,-1),t("img",{src:b},null,-1)])]),_:1}),s[24]||(s[24]=t("p",null,"经过我们的收拾，小房间虽然拥挤，但是还算整齐。",-1)),s[25]||(s[25]=t("p",null,[t("img",{src:x,alt:""})],-1)),l(r,null,{default:p(()=>[...s[6]||(s[6]=[n("弱小的桌子现在承受 2 个人的东西",-1)])]),_:1}),s[26]||(s[26]=t("p",null,"苏小姐来之后最大的变化就是，有人做饭了，而且她的手艺还不错。当然，我洗碗的功底也不差。只是我就很少去吃喜爱的肥肠面了。",-1)),l(o,null,{default:p(()=>[...s[7]||(s[7]=[t("img",{src:P},null,-1),t("img",{src:q},null,-1),t("img",{src:C},null,-1),t("img",{src:k},null,-1),t("img",{src:A},null,-1),t("img",{src:E},null,-1),t("img",{src:S},null,-1),t("img",{src:V},null,-1),t("img",{src:N},null,-1)])]),_:1}),s[27]||(s[27]=t("p",null,"这段时间应该是最快乐的，没有房贷，没有任何负担。我们还经常去参加徒步客，爬爬山。周末就在厦门公园走走。",-1)),s[28]||(s[28]=t("p",null,"如果不是工作变动，我们在海沧这边应该会住很久，哪怕当时在双子塔上班要经历海沧大桥的绝命连环堵车。",-1)),s[29]||(s[29]=t("p",null,"可是，双子塔的公司解散了，我们新工作换到了湖里区，所以我们就从海沧搬到湖里了。",-1)),s[30]||(s[30]=t("video",{src:D,controls:""},null,-1)),l(r,null,{default:p(()=>[...s[8]||(s[8]=[n("一段当时小房间的视频",-1)])]),_:1}),s[31]||(s[31]=e('<h2 id="湖里高林社区-☹️" tabindex="-1">湖里高林社区 ☹️ <a class="header-anchor" href="#湖里高林社区-☹️" aria-label="Permalink to &quot;湖里高林社区 ☹️&quot;">​</a></h2><p>这边的房租好像是 700-800，忘记了。</p><p>在这边的居住体验就非常差了。要么是采光不好，要么就是隔壁住的小年轻半夜打游戏，乱喊乱叫。我过去让他们打游戏小声一点，被那个脏乱差的房间吓到。到处是烟头和饮料瓶，床上被子都煲浆了。</p><p>和房东商量换了一个房间，又遇上隔壁是一个爱请客喝酒的驾校教练，三天两头在家里聚餐吃烤鱼喝啤酒。这类人很喜欢讲社会，请各种朋友来喝着廉价的啤酒，讲着哥们的豪情义气。</p><p>我想不明白，都沦落到住民租房了，怎么生活能那么安逸，而且一把年纪了。</p><p>最终我开始反省自己，为什么会遇上这些烂人。原因就是我贪便宜没有去好点的地方租房子，而是选择了民租房，是我主动选择了低素质人群。</p><p>痛定思痛，<strong>我们决定远离这些烂人，决定再也不在住民租房</strong>。所以，我们搬到了世茂湖滨首府。</p><h2 id="世茂湖滨首府-☹️-😄" tabindex="-1">世茂湖滨首府 ☹️ 😄 <a class="header-anchor" href="#世茂湖滨首府-☹️-😄" aria-label="Permalink to &quot;世茂湖滨首府 ☹️ 😄&quot;">​</a></h2><p>在这边我们租了一个单间，是正规小区，格局就是一个大平房隔出了几个单间。房租是 1600 ，比民租房贵了不少。不过体验确实提升了一点，隔壁住的人不会吵，而且小区绿化超级好，饭后还可以在楼下散步。</p><p>这边离湖边水库也很近，之前有段时间每天下班还去湖边水库走一圈（应该有 5 公里）。</p><p>去宝龙一城也很近，都是步行可达。而且附近也有稿定的班车经过，每天上班去那边等公司的班车即可。</p><p>虽然是个单间，但是有一个还算不小的阳台，我们就在阳台简单的做饭吃饭。条件也算艰苦，不过胜在这边采光好，通风好，整体体验还行。</p>',12)),l(o,null,{default:p(()=>[...s[9]||(s[9]=[t("img",{src:I},null,-1),t("img",{src:v},null,-1)])]),_:1}),l(r,null,{default:p(()=>[...s[10]||(s[10]=[n("这个狭长的桌子就是我们的饭桌",-1)])]),_:1}),s[32]||(s[32]=t("p",null,"要说缺点就是我们这个房间需要和另外一个房间的人共用厕所。这种公共使用的体验就不太好，特别是另外一个房间换成了一个男租客之后。",-1)),s[33]||(s[33]=t("img",{class:"max-w-500 center",src:w},null,-1)),l(r,null,{default:p(()=>[...s[11]||(s[11]=[n("这是我用 Word 做的灵魂海报",-1)])]),_:1}),s[34]||(s[34]=e('<p>后来隔壁换了一批租客，那个两房一厅挤下了可能有 5-6 个人。噪音就多了，也是大晚上的聚餐，吆五喝六。最里面的那个房间之前一直有个男生很安静，后面搬走了，换了个女租客，可能是夜场工作，经常半夜出行，带着一些精神小伙，吵吵闹闹的。</p><img class="max-w-500 center" src="'+G+'"><p>这一切的变化，又提醒着我，该换地方住了。群租的体验也不可控，你的邻居决定了你的居住体验。</p><h2 id="虎仔山庄-☹️-😄" tabindex="-1">虎仔山庄 ☹️ 😄 <a class="header-anchor" href="#虎仔山庄-☹️-😄" aria-label="Permalink to &quot;虎仔山庄 ☹️ 😄&quot;">​</a></h2><p>于是我们搬到了虎仔山庄，是保障房，房东偷偷租给我们的。房租每月 2300</p><p>这边的位置非常好，就在软件园二期东门的正对面，苏小姐上班方便。我来观音山上班也很方便，都是走路可达。</p><p>是非常标准的一室一厅一厨房一阳台一卫生间，是我们租过的房子最板正的格局了。</p><p>而且这边都是正经居家的，人员没没那么混杂。</p><p>但是，没错，又有但是！</p><p>楼上地板经常传来木头摩擦瓷砖的声音，我上去查看，是一个走路需要用凳子支撑的老头在那边走来走去。白天就算了，我都在上班，也听不到，要命的是他都是晚上半夜睡不着起来走。我经常半夜被那个啄、啄、啄的声音吵醒，精神崩溃。</p><p>我上去和对方沟通，那个女老头一脸凶样，说她男人不听劝，没办法，他半夜就是要起来走。我说那你把凳子的脚用布包一下，不至于那么吵。她摆手说弄不了。</p><p>妈的，国家的保障房就是用来养这些败类的，真的是日了狗了。</p><p>好消息是，没多久，我们就搬到自己的房子了，告别了租房的日子。</p><h2 id="碎碎念" tabindex="-1">碎碎念 <a class="header-anchor" href="#碎碎念" aria-label="Permalink to &quot;碎碎念&quot;">​</a></h2><p>从 2014 年开始租房，到 2022 年终于搬入自己的房子。</p><p>一切糟糕的经历都开始远离，我们有了安定的住所。所以我的小宝贝玥玥就姗姗来迟的来到我们身边了。</p><p>是个不爱吃苦的孩子，知道要在自己的房子里出生，需要有她专属的地方玩耍。</p><p><img src="'+M+'" alt=""></p>',18)),l(r,null,{default:p(()=>[...s[12]||(s[12]=[n("宝贝玥玥来做个完美的 ending 吧！",-1)])]),_:1})])}const Y=a(L,[["render",R]]);export{Q as __pageData,Y as default};
